import json,base64,sys,re,datetime
f=sys.argv[1]; lim=int(sys.argv[2]) if len(sys.argv)>2 else 1500
d=json.loads(json.load(open(f))['result'])
def body(p):
    s=''
    if p.get('mimeType','').startswith('text/plain') or not p.get('parts'):
        if p.get('body',{}).get('data'):
            s+=base64.urlsafe_b64decode(p['body']['data']+'==').decode('utf-8','replace')
    for q in p.get('parts',[]) or []: s+=body(q)
    return s
for m in d['messages']:
    h={x['name']:x['value'] for x in m['payload']['headers']}
    t=body(m['payload'])
    t=re.sub(r'\n>.*','',t)
    print('====',datetime.datetime.utcfromtimestamp(int(m['internalDate'])/1000).date(),'|',h.get('From'),'->',h.get('To'),'|',h.get('Subject'))
    print(re.sub(r'\s+',' ',t)[:lim])
